SELECT * FROM class_order
WHERE member_account = #{memberAccount}
ORDER BY create_time DESC

SELECT * FROM class_order
WHERE member_account = #{memberAccount}
  AND status = #{status}
ORDER BY create_time DESC

SELECT * FROM class_order
WHERE coach = #{coach}
ORDER BY create_time DESC

SELECT * FROM class_order
WHERE status = 'BOOKED'
  AND class_begin BETWEEN #{start} AND #{end}
